CREATE TABLE orpa_representation_claims (claim_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),legal_entity_id TEXT NOT NULL REFERENCES legal_entity_identities(legal_entity_id),company_binding_id TEXT NOT NULL REFERENCES legal_entity_company_bindings(binding_id),actor_principal_id TEXT NOT NULL REFERENCES oir_principals(principal_id),membership_id TEXT NOT NULL REFERENCES oir_organization_memberships(membership_id),claimed_position TEXT,representation_basis TEXT NOT NULL,requested_scope TEXT NOT NULL,requested_processing_scope TEXT,requested_policy_ownership_scope TEXT,effective_at TEXT NOT NULL,expires_at TEXT NOT NULL,evidence_references_json TEXT NOT NULL,correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL);
CREATE TABLE orpa_representation_evidence (evidence_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),evidence_class TEXT NOT NULL,actor_principal_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,company_binding_id TEXT NOT NULL,authorized_scopes_json TEXT NOT NULL,issuer_id TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT,superseded_by_evidence_id TEXT,immutable_digest TEXT NOT NULL,governed_reference TEXT NOT NULL UNIQUE,caused_by_json TEXT NOT NULL);
CREATE TABLE orpa_authority_decisions (decision_id TEXT PRIMARY KEY,claim_id TEXT NOT NULL REFERENCES orpa_representation_claims(claim_id),decision TEXT NOT NULL CHECK(decision IN ('GRANTED','DENIED')),approver_id TEXT NOT NULL,reason_codes_json TEXT NOT NULL,decided_at TEXT NOT NULL,correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL);
CREATE TABLE orpa_authorities (authority_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),decision_id TEXT NOT NULL UNIQUE REFERENCES orpa_authority_decisions(decision_id),actor_principal_id TEXT NOT NULL,membership_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,company_binding_id TEXT NOT NULL,oag_proof_id TEXT,representation_evidence_ids_json TEXT NOT NULL,approver_id TEXT NOT NULL,policy_version TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT NOT NULL,lifecycle_state TEXT NOT NULL CHECK(lifecycle_state='ACTIVE'),correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL,grants_execution INTEGER NOT NULL CHECK(grants_execution=0));
CREATE TABLE orpa_authority_scopes (authority_id TEXT NOT NULL REFERENCES orpa_authorities(authority_id),scope TEXT NOT NULL,scope_kind TEXT NOT NULL CHECK(scope_kind IN ('GRANTED','PROHIBITED')),PRIMARY KEY(authority_id,scope,scope_kind));
CREATE TABLE orpa_eligibilities (eligibility_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),authority_id TEXT NOT NULL REFERENCES orpa_authorities(authority_id),actor_principal_id TEXT NOT NULL,membership_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,company_binding_id TEXT NOT NULL,requested_scope TEXT NOT NULL,future_consumer TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,oag_proof_id TEXT,policy_version TEXT NOT NULL,correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL,transferable INTEGER NOT NULL CHECK(transferable=0),executable INTEGER NOT NULL CHECK(executable=0),consumed_at TEXT,consumption_reference TEXT UNIQUE);
CREATE TABLE orpa_authority_transitions (transition_id TEXT PRIMARY KEY,authority_id TEXT NOT NULL UNIQUE REFERENCES orpa_authorities(authority_id),from_state TEXT NOT NULL,to_state TEXT NOT NULL CHECK(to_state IN ('REVOKED','SUPERSEDED')),transition_reference TEXT NOT NULL UNIQUE,transitioned_at TEXT NOT NULL,superseded_by_authority_id TEXT REFERENCES orpa_authorities(authority_id),correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL);
CREATE TABLE orpa_audit_events (audit_event_id TEXT PRIMARY KEY,event_type TEXT NOT NULL,subject_id TEXT NOT NULL,scope TEXT,outcome TEXT NOT NULL,reason_code TEXT,actor_id TEXT NOT NULL,policy_version TEXT NOT NULL,correlation_id TEXT NOT NULL,caused_by_json TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TRIGGER orpa_claim_immutable BEFORE UPDATE ON orpa_representation_claims BEGIN SELECT RAISE(ABORT,'ORPA_CLAIM_IMMUTABLE'); END;
CREATE TRIGGER orpa_claim_no_delete BEFORE DELETE ON orpa_representation_claims BEGIN SELECT RAISE(ABORT,'ORPA_CLAIM_IMMUTABLE'); END;
CREATE TRIGGER orpa_evidence_immutable BEFORE UPDATE ON orpa_representation_evidence BEGIN SELECT RAISE(ABORT,'ORPA_EVIDENCE_IMMUTABLE'); END;
CREATE TRIGGER orpa_evidence_no_delete BEFORE DELETE ON orpa_representation_evidence BEGIN SELECT RAISE(ABORT,'ORPA_EVIDENCE_IMMUTABLE'); END;
CREATE TRIGGER orpa_decision_immutable BEFORE UPDATE ON orpa_authority_decisions BEGIN SELECT RAISE(ABORT,'ORPA_DECISION_IMMUTABLE'); END;
CREATE TRIGGER orpa_decision_no_delete BEFORE DELETE ON orpa_authority_decisions BEGIN SELECT RAISE(ABORT,'ORPA_DECISION_IMMUTABLE'); END;
CREATE TRIGGER orpa_authority_immutable BEFORE UPDATE ON orpa_authorities BEGIN SELECT RAISE(ABORT,'ORPA_AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER orpa_authority_no_delete BEFORE DELETE ON orpa_authorities BEGIN SELECT RAISE(ABORT,'ORPA_AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER orpa_scope_immutable BEFORE UPDATE ON orpa_authority_scopes BEGIN SELECT RAISE(ABORT,'ORPA_SCOPE_IMMUTABLE'); END;
CREATE TRIGGER orpa_scope_no_delete BEFORE DELETE ON orpa_authority_scopes BEGIN SELECT RAISE(ABORT,'ORPA_SCOPE_IMMUTABLE'); END;
CREATE TRIGGER orpa_eligibility_immutable BEFORE UPDATE ON orpa_eligibilities WHEN NOT(OLD.consumed_at IS NULL AND NEW.consumed_at IS NOT NULL AND NEW.consumption_reference IS NOT NULL) BEGIN SELECT RAISE(ABORT,'ORPA_ELIGIBILITY_IMMUTABLE'); END;
CREATE TRIGGER orpa_eligibility_no_delete BEFORE DELETE ON orpa_eligibilities BEGIN SELECT RAISE(ABORT,'ORPA_ELIGIBILITY_IMMUTABLE'); END;
CREATE TRIGGER orpa_transition_immutable BEFORE UPDATE ON orpa_authority_transitions BEGIN SELECT RAISE(ABORT,'ORPA_TRANSITION_IMMUTABLE'); END;
CREATE TRIGGER orpa_transition_no_delete BEFORE DELETE ON orpa_authority_transitions BEGIN SELECT RAISE(ABORT,'ORPA_TRANSITION_IMMUTABLE'); END;
CREATE TRIGGER orpa_audit_immutable BEFORE UPDATE ON orpa_audit_events BEGIN SELECT RAISE(ABORT,'ORPA_AUDIT_IMMUTABLE'); END;
CREATE TRIGGER orpa_audit_no_delete BEFORE DELETE ON orpa_audit_events BEGIN SELECT RAISE(ABORT,'ORPA_AUDIT_IMMUTABLE'); END;
